/**
 * gen-build-id.mjs —— 跨平台生成 BUILD_ID（git short sha 8 位 + yyyymmddhhmmss 时间戳）。
 *
 * 写入 src/build-id.ts（AUTO-GENERATED 注释 + 双引号字符串字面量，无类型注解），
 * 兼容 backend 提取正则 `BUILD_ID\s*=\s*["']([^"']+)`（self-update 链路 R-04）。
 * 注意正则 \s* 不吃冒号 → 不能带 `: string` 注解。
 *
 * 产物形如：
 *   // AUTO-GENERATED by gen-build-id.mjs — do not edit
 *   export const BUILD_ID = "abc12345-20260804112500";
 *
 * 跨平台（Windows / Linux / macOS）：仅用 node >=20 内置模块（fs / path / child_process / url），
 * 不依赖 bash / coreutils（取旧 build-bundle.sh 的 `git rev-parse` + `date` 为 node 实现）。
 *
 * 容错：非 git 目录 / git 命令缺失 / git 非零退出码 → sha 置 "unknown"，脚本始终退出码 0，
 * 保证 postinstall / CI 不会因缺 git 而挂（acceptance: git 失败不抛异常）。
 *
 * 消费方：build-bundle.sh [0/3] 步、package.json postinstall / prepare 钩子（task-03/04 接线）。
 *
 * @module gen-build-id
 */

import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * 取 git short sha（8 位）。
 * 任意失败（非 git 目录 / git 未安装 / 非零退出码 / stdout 为空）一律 fallback "unknown"，
 * 不抛异常 —— 保证脚本退出码 0，postinstall / CI 不会因 git 缺失而挂。
 *
 * @returns {string} 8 位 short sha 或 "unknown"
 */
function getGitShortSha() {
  try {
    const result = spawnSync('git', ['rev-parse', '--short=8', 'HEAD'], {
      encoding: 'utf8',
      // 不继承 stdio → 不让 git 报错污染调用方日志（fallback 时静默）
      stdio: ['ignore', 'pipe', 'ignore'],
    });
    if (result.status !== 0 || result.error) {
      return 'unknown';
    }
    const sha = (result.stdout || '').trim();
    // 形如 "abc12345"；空串 / 超长 / 含空白 / 非 hex 一律视为失败
    if (!sha || !/^[0-9a-f]{7,40}$/i.test(sha)) {
      return 'unknown';
    }
    return sha;
  } catch {
    return 'unknown';
  }
}

/**
 * 生成 yyyymmddhhmmss 时间戳（本地时间，padStart 补零）。
 *
 * 设计选择：用本地时间，与旧 build-bundle.sh 的 `date +%Y%m%d%H%M%S` 行为对齐
 * （shell `date` 默认就是本地时间）。CI 跨时区时戳会跟随 runner 本地时区，
 * 仅作可读性标识，不参与版本比较（版本比较走 git sha + daemon semver）。
 *
 * @param {Date} [now=new Date()] 注入用入口，便于测试
 * @returns {string} 14 位时间戳 yyyymmddhhmmss
 */
function formatTimestamp(now = new Date()) {
  const y = String(now.getFullYear()).padStart(4, '0');
  const mo = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  const h = String(now.getHours()).padStart(2, '0');
  const mi = String(now.getMinutes()).padStart(2, '0');
  const s = String(now.getSeconds()).padStart(2, '0');
  return `${y}${mo}${d}${h}${mi}${s}`;
}

/**
 * 主流程：生成 BUILD_ID 并写入 src/build-id.ts。
 *
 * 路径解析相对脚本所在目录（`import.meta.dirname`），不依赖 cwd ——
 * 这样无论从 sillyhub-daemon / 仓库根 / CI 任意目录调用都能写到正确的 src/build-id.ts。
 */
function main() {
  const sha = getGitShortSha();
  const ts = formatTimestamp();
  const buildId = `${sha}-${ts}`;

  // 脚本位于 sillyhub-daemon/scripts/，目标在 sillyhub-daemon/src/build-id.ts
  const scriptDir = path.dirname(fileURLToPath(import.meta.url));
  const outFile = path.resolve(scriptDir, '..', 'src', 'build-id.ts');

  // 双引号 + 无类型注解：兼容 backend 正则 BUILD_ID\s*=\s*["']。
  // 注意：正则的 \s* 不吃冒号，故不能带 `: string` 注解，否则 self-update 提取失败（R-04）。
  const content =
    '// AUTO-GENERATED by gen-build-id.mjs — do not edit\n' +
    `export const BUILD_ID = "${buildId}";\n`;

  writeFileSync(outFile, content, 'utf8');

  // CI 日志追溯用（acceptance: 控制台打印 BUILD_ID=<值>）
  console.log(`BUILD_ID=${buildId}`);
  console.log(`-> wrote ${outFile}`);
}

main();
